/**
 * The one launch path: channel gate, v1 launch with the mount's model,
 * principal binding, and the stop watch. `cloud__launch` calls it with the
 * mount's repositories; an authored tool can call it with its own
 * `cloud` target (a named saved environment, say) and its own `model` after
 * applying its own gates, and the launched agent is then steerable with the
 * mount's `get` / `dump` / `reply` / `cancel` like any other, or with
 * {@link followUpCloudAgent} from authored code.
 */
import { cloudAgentUrl } from "../../../internal/cursor/credentials.js";
import extension from "../extension.js";
import { cloudAgentsBackend, } from "./backend.js";
import { assertWriteChannel } from "./channels.js";
import { assertOwned, recordLaunch } from "./fleet.js";
import { armWatch } from "./watch.js";
export async function launchCloudAgent(ctx, request) {
    assertWriteChannel(ctx);
    const launched = await cloudAgentsBackend().launch({
        prompt: request.prompt,
        name: request.name,
        model: request.model ?? extension.config.model,
        cloud: request.cloud,
    });
    await recordLaunch(ctx, launched.agentId, request.name);
    return { ...launched, watching: await armWatch(ctx, launched) };
}
/**
 * Queue a follow-up on an agent this principal launched, with the same
 * channel gate and ownership check as `cloud__reply`, then watch the agent
 * again: the launch's stop watch ends at the first stop, so without this the
 * conversation is never woken when the follow-up run stops.
 */
export async function followUpCloudAgent(ctx, request) {
    const { agentId, prompt } = request;
    assertWriteChannel(ctx);
    await assertOwned(ctx, agentId);
    const { runId } = await cloudAgentsBackend().followUp(agentId, prompt, request.interrupt === true);
    const watching = await armWatch(ctx, {
        agentId,
        runId: runId ?? "",
        status: "running",
        url: cloudAgentUrl(agentId),
    });
    return { runId, watching };
}
/**
 * One agent's status, branch, pull request, summary, and error under the
 * mount's API key. Unlike `cloud__get` there is no principal check, so pass
 * only ids authored code launched (a reminder that reports its own launch's
 * outcome), never an id a model chose.
 */
export function getCloudAgent(agentId) {
    return cloudAgentsBackend().info(agentId);
}
/** A saved environment by public id under the mount's API key; undefined when not visible. */
export function getCloudEnvironment(publicId) {
    return cloudAgentsBackend().environment(publicId);
}
/** Visible saved environments whose display name is exactly `name`. */
export function listCloudEnvironmentsNamed(name) {
    return cloudAgentsBackend().environmentsNamed(name);
}
